<?php $title='Roles & Permissions';require __DIR__.'/../layouts/header.php';?><div class="pagehead"><div><h1>Roles & Permissions</h1><p>Stage-based permissions are enforced server-side.</p></div></div><div class="panel"><form method="post" action="<?=route('admin.roles')?>"><?=csrf_field()?><label>Role<select name="role_id" onchange="this.form.method='get';this.form.action='<?=route('admin.roles')?>';this.form.submit()"><?php foreach($roles as $r):?><option value="<?=$r['id']?>" <?=$selected===$r['id']?'selected':''?>><?=e($r['role_name'])?></option><?php endforeach;?></select></label><div class="permission-grid"><?php foreach($permissions as $p):?><label class="permission"><input type="checkbox" name="permissions[]" value="<?=$p['id']?>" <?=in_array((int)$p['id'],$assigned,true)?'checked':''?>><span><?=e($p['module_name'])?> · <?=e($p['permission_label'])?></span><small><?=e($p['stage'])?></small></label><?php endforeach;?></div><button class="primary">Save permissions</button></form></div><?php require __DIR__.'/../layouts/footer.php';?>
